@Composable fun SettingsScreen(vm:VigilViewModel){val o by vm.options.collectAsStateWithLifecycle();val all by vm.quotes.collectAsStateWithLifecycle();val runs by vm.runs.collectAsStateWithLifecycle();val current=runs.firstOrNull { it.end==null };val c=LocalContext.current;var sheet by rememberSaveable { mutableStateOf("") };var denied by remember { mutableStateOf(false) };val perm=rememberLauncherForActivityResult(ActivityResultContracts.RequestPermission()){granted->denied=!granted;if(granted)vm.notifications(true,o.minute,o.quoteNotice)};val backup=rememberLauncherForActivityResult(ActivityResultContracts.CreateDocument("application/json")){it?.let(vm::export)};val restore=rememberLauncherForActivityResult(ActivityResultContracts.OpenDocument()){it?.let(vm::restore)}
